PROCEDURE GET_CUSTOMER_ORDERS (
    p_customer_id IN NUMBER,
    p_cursor OUT SYS_REFCURSOR
) AS
BEGIN
    OPEN p_cursor FOR
        SELECT o.OrderID, o.OrderDate, o.Quantity, p.ProductName, p.Price
        FROM Orders o
        JOIN Product p ON o.ProductID = p.ProductID
        WHERE o.CustomerID = p_customer_id
        ORDER BY o.OrderDate DESC;
EXCEPTION
    WHEN NO_DATA_FOUND THEN
        DBMS_OUTPUT.PUT_LINE('No orders found for customer ' || p_customer_id);
    WHEN OTHERS THEN
        DBMS_OUTPUT.PUT_LINE('Error: ' || SQLERRM);
        RAISE;
END GET_CUSTOMER_ORDERS;
